def link(modules, main):
    by_name = {}
    owner = {}
    for name, defines, needs in modules:
        by_name[name] = needs
        for s in defines:
            owner[s] = name
    order = []
    def visit(name):
        if name in order:
            return None
        order.append(name)
        for s in by_name[name]:
            if s not in owner:
                return "undefined: " + s
            r = visit(owner[s])
            if r:
                return r
        return None
    err = visit(main)
    if err:
        return err
    return order

