def first_sets(g):
    nts = []
    for lhs, rhs in g:
        if lhs not in nts:
            nts.append(lhs)
    first = {}
    for n in nts:
        first[n] = set()
    changed = True
    while changed:
        changed = False
        for lhs, rhs in g:
            before = len(first[lhs])
            all_eps = True
            for sym in rhs:
                if sym in first:
                    first[lhs] |= (first[sym] - {'ε'})
                    if 'ε' not in first[sym]:
                        all_eps = False
                        break
                else:
                    first[lhs].add(sym)
                    all_eps = False
                    break
            if all_eps:
                first[lhs].add('ε')
            if len(first[lhs]) != before:
                changed = True
    return [[n, sorted(first[n])] for n in nts]

def follow_sets(g):
    nts = []
    for lhs, rhs in g:
        if lhs not in nts:
            nts.append(lhs)
    first = {}
    for n in nts:
        first[n] = set()
    changed = True
    while changed:
        changed = False
        for lhs, rhs in g:
            before = len(first[lhs])
            all_eps = True
            for sym in rhs:
                if sym in first:
                    first[lhs] |= (first[sym] - {'ε'})
                    if 'ε' not in first[sym]:
                        all_eps = False
                        break
                else:
                    first[lhs].add(sym)
                    all_eps = False
                    break
            if all_eps:
                first[lhs].add('ε')
            if len(first[lhs]) != before:
                changed = True
    follow = {}
    for n in nts:
        follow[n] = set()
    follow[nts[0]].add('$')
    changed = True
    while changed:
        changed = False
        for lhs, rhs in g:
            for i in range(len(rhs)):
                b = rhs[i]
                if b not in follow:
                    continue
                before = len(follow[b])
                vanish = True
                for sym in rhs[i + 1:]:
                    if sym in first:
                        follow[b] |= (first[sym] - {'ε'})
                        if 'ε' not in first[sym]:
                            vanish = False
                            break
                    else:
                        follow[b].add(sym)
                        vanish = False
                        break
                if vanish:
                    follow[b] |= follow[lhs]
                if len(follow[b]) != before:
                    changed = True
    return [[n, sorted(follow[n])] for n in nts]

