def backtrack(g, start, s):
    tries = [0]
    def parse(seq, i):
        if seq == '':
            return i == len(s)
        sym = seq[0]
        if sym.isupper():
            for alt in g[sym]:
                tries[0] += 1
                if parse(alt + seq[1:], i):
                    return True
            return False
        if i < len(s) and s[i] == sym:
            return parse(seq[1:], i + 1)
        return False
    ok = parse(start, 0)
    return [ok, tries[0]]

