def ll1_parse(table, start, tokens):
    stack = ['$', start]
    toks = tokens + ['$']
    i = 0
    out = []
    while stack:
        x = stack.pop()
        a = toks[i]
        if x not in table:
            if x == a:
                if x == '$':
                    return out
                i += 1
            else:
                return ['error']
        else:
            rhs = table[x].get(a)
            if rhs is None:
                return ['error']
            out.append(x + ' -> ' + (' '.join(rhs) if rhs else 'ε'))
            for sym in reversed(rhs):
                stack.append(sym)
    return ['error']

def rd_eval(tokens):
    pos = [0]
    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None
    def expr():
        v = term()
        while peek() == '+':
            pos[0] += 1
            v = v + term()
        return v
    def term():
        v = factor()
        while peek() == '*':
            pos[0] += 1
            v = v * factor()
        return v
    def factor():
        t = peek()
        if t is None:
            raise ValueError('eof')
        if t == '(':
            pos[0] += 1
            v = expr()
            if peek() != ')':
                raise ValueError('paren')
            pos[0] += 1
            return v
        if t.isdigit():
            pos[0] += 1
            return int(t)
        raise ValueError('bad')
    try:
        v = expr()
        if pos[0] != len(tokens):
            return 'error'
        return v
    except ValueError:
        return 'error'

