def lr_parse(action, goto, rules, tokens):
    toks = tokens + ['$']
    stack = ['0']
    i = 0
    out = []
    while True:
        s = stack[-1]
        a = action.get(s, {}).get(toks[i])
        if a is None:
            return ['error']
        if a == 'acc':
            out.append('accept')
            return out
        if a[0] == 's':
            out.append('shift ' + toks[i])
            stack.append(a[1:])
            i += 1
        else:
            left, n = rules[a[1:]]
            for _ in range(n):
                stack.pop()
            out.append('reduce ' + left)
            nxt = goto.get(stack[-1], {}).get(left)
            if nxt is None:
                return ['error']
            stack.append(nxt)

