def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
    return not stack

def build_ast(tokens):
    pos = [0]
    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None
    def expr():
        left = term()
        while peek() in ['+', '-']:
            op = tokens[pos[0]]
            pos[0] += 1
            left = [op, left, term()]
        return left
    def term():
        left = factor()
        while peek() in ['*', '/']:
            op = tokens[pos[0]]
            pos[0] += 1
            left = [op, left, factor()]
        return left
    def factor():
        t = tokens[pos[0]]
        pos[0] += 1
        if t == '(':
            e = expr()
            pos[0] += 1
            return e
        return t
    return expr()

