def type_check(decls, stmts):
    table = {}
    errors = []
    for name, t in decls:
        if name in table:
            errors.append('redeclared: ' + name)
        else:
            table[name] = t
    for target, value in stmts:
        if target not in table:
            errors.append('undeclared: ' + target)
            continue
        if value.startswith('"'):
            vt = 'string'
        elif value.replace('.', '', 1).isdigit():
            vt = 'float' if '.' in value else 'int'
        elif value in table:
            vt = table[value]
        else:
            errors.append('undeclared: ' + value)
            continue
        tt = table[target]
        if vt != tt and not (tt == 'float' and vt == 'int'):
            errors.append('type mismatch: ' + target)
    return errors

def annotate(tree):
    if tree[0] == 'int' or tree[0] == 'float':
        return [tree[1], tree[0]]
    op, l, r = tree
    lv, lt = annotate(l)
    rv, rt = annotate(r)
    if op == '+':
        v = lv + rv
    elif op == '-':
        v = lv - rv
    else:
        v = lv * rv
    return [v, 'float' if 'float' in (lt, rt) else 'int']

def activation_tree(events):
    stack = []
    root = None
    for e in events:
        if e == 'return':
            stack.pop()
        else:
            node = [e.split(' ', 1)[1], []]
            if stack:
                stack[-1][1].append(node)
            else:
                root = node
            stack.append(node)
    return root

def max_depth(events):
    d = 0
    best = 0
    for e in events:
        if e == 'return':
            d -= 1
        else:
            d += 1
            if d > best:
                best = d
    return best

