def symtab(ops):
    scopes = [{}]
    out = []
    for op in ops:
        if op[0] == 'enter':
            scopes.append({})
            out.append('ok')
        elif op[0] == 'exit':
            if len(scopes) == 1:
                out.append('error')
            else:
                scopes.pop()
                out.append('ok')
        elif op[0] == 'insert':
            if op[1] in scopes[-1]:
                out.append('duplicate')
            else:
                scopes[-1][op[1]] = op[2]
                out.append('ok')
        else:
            found = 0
            for sc in reversed(scopes):
                if op[1] in sc:
                    found = sc[op[1]]
                    break
            out.append(found)
