def simplify(code):
    out = []
    shifts = {'2': '1', '4': '2', '8': '3'}
    for ins in code:
        op, rest = ins.split(' ', 1)
        reg, val = [x.strip() for x in rest.split(',')]
        if op in ['ADD', 'SUB'] and val == '0':
            continue
        if op in ['MUL', 'DIV'] and val == '1':
            continue
        if op == 'ADD' and val == '1':
            out.append('INC ' + reg)
        elif op == 'MUL' and val in shifts:
            out.append('SHL ' + reg + ', ' + shifts[val])
        else:
            out.append(ins)
    return out

def remove_unreachable(code):
    out = []
    dead = False
    for ins in code:
        if ins.endswith(':'):
            dead = False
            out.append(ins)
        elif dead:
            continue
        else:
            out.append(ins)
            if ins == 'RET' or ins.startswith('GOTO'):
                dead = True
    return out

def thread_jumps(code):
    nxt = {}
    for i in range(len(code) - 1):
        if code[i].endswith(':') and code[i + 1].startswith('GOTO '):
            nxt[code[i][:-1]] = code[i + 1].split(' ')[1]
    def final(lab):
        seen = [lab]
        while lab in nxt:
            lab = nxt[lab]
            if lab in seen:
                break
            seen.append(lab)
        return lab
    out = []
    for ins in code:
        parts = ins.split(' ')
        if len(parts) == 2 and parts[0] in ['GOTO', 'JNZ', 'JZ']:
            out.append(parts[0] + ' ' + final(parts[1]))
        else:
            out.append(ins)
    return out

def dag_ops(stmts):
    node_of = {}
    nodes = {}
    count = [0]
    def leaf(name):
        if name not in node_of:
            count[0] += 1
            node_of[name] = ('leaf', count[0])
        return node_of[name]
    ops = 0
    for target, op, a, b in stmts:
        na = leaf(a)
        nb = leaf(b)
        if op in ['+', '*'] and str(nb) < str(na):
            na, nb = nb, na
        key = (op, na, nb)
        if key not in nodes:
            nodes[key] = ('op', len(nodes))
            ops += 1
        node_of[target] = nodes[key]
    return ops

def codegen(stmts):
    names = {'+': 'ADD', '-': 'SUB', '*': 'MUL'}
    reg_of = {}
    nxt = [0]
    out = []
    def loc(n):
        return reg_of.get(n, n)
    for x, op, y, z in stmts:
        if y.startswith('t') and y in reg_of:
            r = reg_of.pop(y)
        else:
            r = 'R' + str(nxt[0])
            nxt[0] += 1
            out.append('MOV ' + loc(y) + ', ' + r)
        if op != '=':
            out.append(names[op] + ' ' + loc(z) + ', ' + r)
        reg_of[x] = r
        if not x.startswith('t'):
            out.append('MOV ' + r + ', ' + x)
    return out

