def basic_blocks(lines):
    targets = set()
    for ln in lines:
        w = ln.split(' ')
        if 'goto' in w:
            targets.add(w[-1])
    leaders = set([0])
    for i in range(len(lines)):
        ln = lines[i]
        if ln.endswith(':') and ln[:-1] in targets:
            leaders.add(i)
        if 'goto' in ln.split(' ') and i + 1 < len(lines):
            leaders.add(i + 1)
    blocks = []
    for i in range(len(lines)):
        if i in leaders:
            blocks.append([])
        blocks[-1].append(lines[i])
    return blocks

